tool_input.command:
$procs = Get-CimInstance Win32_Process -Filter "Name='cmd.exe'" -EA SilentlyContinue
"cmd.exe count=$($procs.Count)"
foreach ($p in $procs) {
  $parent = Get-CimInstance Win32_Process -Filter "ProcessId=$($p.ParentProcessId)" -EA SilentlyContinue
  "PID=$($p.ProcessId) PPID=$($p.ParentProcessId) PNAME=[$($parent.Name)] CREATED=$($p.CreationDate)"
  "  CMD=[$($p.CommandLine)]"
}
"--- openviking-server ---"
Get-CimInstance Win32_Process -Filter "Name='openviking-server.exe'" -EA SilentlyContinue | ForEach-Object { "PID=$($_.ProcessId) PPID=$($_.ParentProcessId) CREATED=$($_.CreationDate) CMD=[$($_.CommandLine)]" }
"--- wscript ---"
Get-CimInstance Win32_Process -Filter "Name='wscript.exe'" -EA SilentlyContinue | ForEach-Object { "PID=$($_.ProcessId) CREATED=$($_.CreationDate) CMD=[$($_.CommandLine)]" }
"--- ollama ---"
Get-CimInstance Win32_Process -Filter "Name='ollama.exe'" -EA SilentlyContinue | ForEach-Object { "PID=$($_.ProcessId) CMD=[$($_.CommandLine)]" }

function ProcInfo($id) { $p = Get-CimInstance Win32_Process -Filter "ProcessId=$id" -EA SilentlyContinue; if ($p) { "PID=$id NAME=$($p.Name) PPID=$($p.ParentProcessId) CREATED=$($p.CreationDate) CMD=[$($p.CommandLine)]" } else { "PID=$id <gone>" } }

"=== 两个可见 cmd 窗口的子进程 ==="
foreach ($pid0 in @(23808,8928)) {
  "--- window cmd $pid0 ---"
  ProcInfo $pid0
  $kids = Get-CimInstance Win32_Process -Filter "ParentProcessId=$pid0" -EA SilentlyContinue
  foreach ($k in $kids) { "  CHILD: PID=$($k.ProcessId) NAME=$($k.Name) CMD=[$($k.CommandLine)]" }
}

"=== 端口归属 3080(dsh web) / 1933(OV) ==="
foreach ($port in @(3080,1933)) {
  $c = Get-NetTCPConnection -LocalPort $port -State Listen -EA SilentlyContinue | Select-Object -First 1
  if ($c) { "PORT $port -> PID $($c.OwningProcess)"; ProcInfo $c.OwningProcess } else { "PORT $port no listener" }
}

"=== node (dsh web) 进程 ==="
Get-CimInstance Win32_Process -Filter "Name='node.exe'" -EA SilentlyContinue | ForEach-Object { "PID=$($_.ProcessId) PPID=$($_.ParentProcessId) CMD=[$($_.CommandLine)]" }

$p = Get-CimInstance Win32_Process -Filter "ProcessId=23808" -EA SilentlyContinue
if (-not $p) { "PID 23808 已不存在"; return }
$kids = Get-CimInstance Win32_Process -Filter "ParentProcessId=23808" -EA SilentlyContinue | Where-Object { $_.Name -ne 'conhost.exe' }
"复核: PID=23808 NAME=$($p.Name) PPID=$($p.ParentProcessId) CMD=[$($p.CommandLine)] 业务子进程=$($kids.Count)"
if ($p.Name -eq 'cmd.exe' -and $p.ParentProcessId -eq 2524 -and $kids.Count -eq 0) {
  Stop-Process -Id 23808 -Force
  Start-Sleep -Milliseconds 500
  "已关闭 23808; 是否存在=$( [bool](Get-Process -Id 23808 -EA SilentlyContinue) )"
} else { "复核不通过，未操作" }
"=== 关闭后关键服务状态 ==="
"dsh web 3080: $([bool](Get-NetTCPConnection -LocalPort 3080 -State Listen -EA SilentlyContinue))  (node 17652 alive=$([bool](Get-Process -Id 17652 -EA SilentlyContinue)))"
try { $r=Invoke-WebRequest 'http://127.0.0.1:1933/health' -UseBasicParsing -TimeoutSec 3; "OV health: HTTP $($r.StatusCode) $($r.Content)" } catch { "OV health: DOWN" }
"剩余可见 cmd 窗口: $((Get-Process cmd -EA SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | ForEach-Object { $_.Id }) -join ',')"
